SELECT  FROM mig_preflight_error
WHERE tenant_id=#{tenantId} AND batch_id=#{batchId}
ORDER BY data_type,row_number,error_id LIMIT 500

SELECT  FROM mig_preflight_error
WHERE tenant_id=#{tenantId} AND batch_id=#{batchId}
ORDER BY data_type,row_number,error_id LIMIT #{limit} OFFSET #{offset}

SELECT  FROM mig_staging_row
WHERE tenant_id=#{tenantId} AND batch_id=#{batchId}
ORDER BY FIELD(data_type,'CATALOG','SUPPLIER','MEMBER','OPENING_INVENTORY'),row_number,row_id

SELECT approval_id AS approvalId,batch_id AS batchId,approver_user_id AS approverUserId,
  reason_sha256 AS reasonSha256,idempotency_key AS idempotencyKey
FROM mig_approval WHERE tenant_id=#{tenantId} AND batch_id=#{batchId} AND idempotency_key=#{key}
